package com.andye.warmod.radar.network;
import com.andye.warmod.WarMod;import com.andye.warmod.radar.RadarTerrainTile;import java.util.*;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record ClientboundRadarTerrainBatchPayload(List<RadarTerrainTile> tiles) implements CustomPacketPayload{public static final Type<ClientboundRadarTerrainBatchPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"radar_terrain_batch"));public static final StreamCodec<RegistryFriendlyByteBuf,ClientboundRadarTerrainBatchPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeVarInt(p.tiles.size());for(RadarTerrainTile t:p.tiles){b.writeInt(t.chunkX());b.writeInt(t.chunkZ());for(int c:t.colours())b.writeInt(c);for(short h:t.heights())b.writeShort(h);}},b->{int n=RadarNetworkCodecs.count(b,128);List<RadarTerrainTile> ts=new ArrayList<>(n);for(int i=0;i<n;i++){int x=b.readInt(),z=b.readInt();int[] c=new int[64];short[] h=new short[64];for(int j=0;j<64;j++)c[j]=b.readInt();for(int j=0;j<64;j++)h[j]=b.readShort();ts.add(new RadarTerrainTile(x,z,c,h));}return new ClientboundRadarTerrainBatchPayload(ts);});public ClientboundRadarTerrainBatchPayload{tiles=List.copyOf(tiles);if(tiles.size()>128)throw new IllegalArgumentException("Too many tiles");}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
